from typing import List

class Solution:
    def countPrefixSuffixPairs(self, words: List[str]) -> int:
        count = 0
        n = len(words)
        for i in range(n - 1):
            for j in range(i + 1, n):
                if len(words[i]) <= len(words[j]) and \
                   words[j].startswith(words[i]) and words[j].endswith(words[i]):
                    count += 1
        return count
